### 3.5. `src/server.js` (Express + endpoints)

```js
// ---------- Imports ----------
const express = require('express');
const cors = require('cors');
const bodyParser = require('body-parser');
const axios = require('axios'); // para gerar QR e enviar PIX

const app = express();
app.use(cors());
app.use(bodyParser.json());

// ---------- Dados simulados ----------
let messages = []; // [{id, text, sender}]
let sponsors = []; // [{name, contrib}]

// ---------- Endpoint: form-submit ----------
app.post('/api/form-submit', async (req, res) => {
  const {message} = req.body;
  const id = Date.now(); // simples ID
  messages.push({id, text: message, sender: 'Usuário'});

  // Atualizar ranking (aqui você poderia calcular quem tem mais mensagens)
  // Exemplo: contar ocorrências de cada nome...

  // Retirar as 3 mais recentes das mensagens
  messages.sort((a,b)=>b.id-a.id).slice(0,3);

  // Resposta para front‑end
  res.json({msgId: id, text: message, sender: 'Usuário'});
});

// ---------- Helper: gerar PNG da mensagem ----------
async function generatePixImage(text) {
  // Exemplo usando Canvas (não otimizado)
  const canvas = document.createElement('canvas');
  canvas.width = 400;
  canvas.height = 200;
  const ctx = canvas.getContext('2d');
  ctx.fillStyle = '#fff';
  ctx.font = 'bold 24px Arial';
  ctx.fillText(text, 100, 90);
  // Exportar como base64 (para enviar via API)
  const imgBuffer = canvas.toDataURL('image/png');
  return imgBuffer; // string base64
}

// ---------- Endpoint: enviar PIX ----------
app.post('/api/send-pix', async (req, res) => {
  const {to, content, label} = req.body; // to = telegram id, content = texto, label = descrição
  try {
    // Simulação da chamada à API do Mercado Pago
    const pixRes = await axios.post('https://api.marketpay.com/v1/pix/send', {
      to: to,
      content: content,
      label: label,
      // adicione campos adicionais conforme a API
    }, {headers:{'Authorization': 'Bearer YOUR_PIX_TOKEN'}});
    res.json({status:'ok', pixId:pixRes.data.id});
  } catch (err) {
    console.error(err);
    res.status(500).json({error:'PIX falhou'});
  }
});

// ---------- Início ----------
const PORT = process.env.PORT || 3000;
app.listen(PORT, () => console.log(`Servidor rodando em http://localhost:${PORT}`));
```

#### Como adaptar ao seu Mercado Pago

- Substitua `YOUR_PIX_TOKEN` pela chave de acesso real.
- Verifique a documentação da API do Mercado Pago para os campos esperados (`to`, `content`, `label`, etc.).
- Se a API exigir autenticação JWT, adicione o header apropriado.

